mapper.select:
SELECT path, store_name, extension, state AS deleted FROM file WHERE CONCAT(store_name, extension) = #{fileName}
UNION ALL
SELECT path, store_name, extension, false AS deleted FROM thumbnail WHERE CONCAT(store_name, extension) = #{fileName}

SELECT EXISTS (
SELECT 1
FROM file_cleanup_task
WHERE source_path = #{relativePath}
OR destination_path = #{relativePath}
)
